"""A visible "AI-generated by Muse Image" label burned into any image made from a Muse Image output (a composite, a
video still): the re-encode drops Meta's AI tag, and Meta's AUP asks that outputs keep their provenance signals. This
ffmpeg has no drawtext, so the label is drawn in a 5x7 dot font. The untouched .webp is what share/ keeps."""
import subprocess

LABEL = "AI-generated by Muse Image"
IMAGE_PX_PER_DOT = 320  # the label is 157 dots wide, so it spans about half the image
FONT = {  # 5x7 dots, only the capitals the label needs
    "A": ".###. #...# #...# ##### #...# #...# #...#", "B": "####. #...# #...# ####. #...# #...# ####.",
    "D": "####. #...# #...# #...# #...# #...# ####.", "E": "##### #.... #.... ####. #.... #.... #####",
    "G": ".###. #...# #.... #.### #...# #...# .####", "I": ".###. ..#.. ..#.. ..#.. ..#.. ..#.. .###.",
    "M": "#...# ##.## #.#.# #.#.# #...# #...# #...#", "N": "#...# #...# ##..# #.#.# #..## #...# #...#",
    "R": "####. #...# #...# ####. #.#.. #..#. #...#", "S": ".#### #.... #.... .###. ....# ....# ####.",
    "T": "##### ..#.. ..#.. ..#.. ..#.. ..#.. ..#..", "U": "#...# #...# #...# #...# #...# #...# .###.",
    "Y": "#...# #...# .#.#. ..#.. ..#.. ..#.. ..#..", "-": "..... ..... ..... ##### ..... ..... .....",
    " ": "..... ..... ..... ..... ..... ..... .....",
}


def dots(text):
    """`text` in capitals as a binary PGM: white dots on a black box with one dot of margin."""
    glyphs = [FONT[c].split() for c in text.upper()]
    width, height = 6 * len(glyphs) + 1, 9
    lit = {(6 * i + x + 1, y + 1) for i, glyph in enumerate(glyphs) for y, row in enumerate(glyph)
           for x, dot in enumerate(row) if dot == "#"}
    pixels = bytes(255 if (x, y) in lit else 0 for y in range(height) for x in range(width))
    return f"P5 {width} {height} 255\n".encode() + pixels


def burn(image, out_path, text=LABEL):
    """A copy of `image` with `text` in its lower-left corner, as JPG or PNG (this ffmpeg writes no WebP)."""
    width = int(subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width",
                                "-of", "csv=p=0", str(image)], check=True, capture_output=True, text=True).stdout)
    scale = max(1, width // IMAGE_PX_PER_DOT)
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", str(image), "-f", "pgm_pipe", "-i", "pipe:0", "-filter_complex",
                    f"[1]scale=iw*{scale}:ih*{scale}:flags=neighbor[l];[0][l]overlay={scale}:H-h-{scale}",
                    "-frames:v", "1", str(out_path)], input=dots(text), check=True)
    return out_path
